<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($pageTitle ?? 'User Account') ?></title>
<style>:root{--navy:#12385f;--blue:#1c5b96;--teal:#16877e;--ink:#1e3043;--muted:#64788c;--line:#dce6f1;--bg:#f1f6fb}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f4f8fc,#eaf2f9);font-family:Segoe UI,Arial,sans-serif;color:var(--ink)}header{background:linear-gradient(115deg,#0b3768,#155a91 65%,#147e82);color:#fff;padding:22px clamp(16px,4vw,42px);display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}h1{margin:5px 0;font-size:28px}.eyebrow{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#c7e9f7;font-weight:700}header p{margin:0;color:#e0edf8;font-size:13px}.btn{display:inline-block;border:1px solid #cfdae7;border-radius:9px;padding:10px 14px;font-weight:700;font-size:13px;text-decoration:none;background:#fff;color:#12385f;cursor:pointer}.primary{background:linear-gradient(110deg,#164b7b,#14877e);color:#fff;border:0}.wrap{max-width:1000px;margin:24px auto;padding:0 18px 35px}.panel{background:#fff;border:1px solid var(--line);border-radius:15px;padding:22px;box-shadow:0 5px 20px #15395e09;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}label{font-size:12px;font-weight:700;color:#40566b}input,select{width:100%;border:1px solid #cfdae7;border-radius:9px;padding:11px 12px;font:14px Segoe UI,Arial,sans-serif;background:#fff;color:#203b57}input:focus,select:focus{outline:2px solid #4b8bc933;border-color:#4b8bc9}.hint{font-size:12px;color:#64788c}.section-title{color:#12385f;font-size:17px;margin:0 0 16px}.alert{padding:12px 14px;border-radius:9px;margin-bottom:10px;background:#fff0f0;border:1px solid #f0bcbc;color:#8e2a2a;font-size:13px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.notice{background:#eef7ff;border:1px solid #d5e7f8;border-radius:10px;padding:12px;font-size:12px;color:#315b7d;margin-bottom:16px}@media(max-width:650px){.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.panel{padding:15px}}</style></head><body>
<header><div><div class="eyebrow">MCQ Bank · Administration</div><h1><?= esc($pageTitle ?? 'User Account') ?></h1><p>Create or update login details and linked faculty identity.</p></div><a class="btn" href="<?= site_url('master/admin/users') ?>">← Users &amp; Faculty</a></header>
<main class="wrap"><section class="panel">
<?php foreach (($errors ?? []) as $message): ?><div class="alert"><?= esc($message) ?></div><?php endforeach; ?>
<?php if ($msg = session()->getFlashdata('error')): ?><div class="alert"><?= esc($msg) ?></div><?php endif; ?>
<div class="notice">Account roles: Super Administrator, Administrator, Teaching Faculty, or Teaching Faculty / Reviewer. Faculty accounts require department and subject details. Existing linked faculty records are preserved.</div>
<form method="post" action="<?= site_url('master/admin/users/save') ?>"><?= csrf_field() ?><input type="hidden" name="UserID" value="<?= esc(old('UserID', $user['UserID'] ?? '')) ?>">
<div class="grid">
<div class="field"><label for="FullName">Full name *</label><input id="FullName" name="FullName" maxlength="255" required value="<?= esc(old('FullName', $user['FullName'] ?? '')) ?>"></div>
<div class="field"><label for="UserName">Username *</label><input id="UserName" name="UserName" maxlength="255" required autocomplete="username" value="<?= esc(old('UserName', $user['UserName'] ?? '')) ?>"></div>
<div class="field"><label for="Password">Password <?= empty($user['UserID']) ? '*' : '(leave blank to keep current password)' ?></label><input id="Password" type="password" name="Password" <?= empty($user['UserID'])?'required':'' ?> minlength="8" autocomplete="new-password"><span class="hint">At least 8 characters. Passwords are never displayed.</span></div>
<div class="field"><label for="RollID">Account role *</label><select id="RollID" name="RollID" required><option value="">Select role</option><?php foreach ([0=>'Super Administrator',1=>'Administrator',2=>'Teaching Faculty',3=>'Teaching Faculty / Reviewer'] as $rid=>$rlabel): ?><option value="<?= $rid ?>" <?= (string)old('RollID',$user['RollID']??'')===(string)$rid?'selected':'' ?>><?= esc($rlabel) ?></option><?php endforeach; ?></select><span class="hint">Stored in the existing RollID column.</span></div>
</div>
<div id="facultyFields" style="margin-top:24px"><h2 class="section-title">Faculty record (required for faculty roles)</h2><div class="grid">
<div class="field"><label for="author_name">Faculty display name</label><input id="author_name" name="author_name" maxlength="255" value="<?= esc(old('author_name', $user['author']['author_name'] ?? ($user['FullName'] ?? ''))) ?>"></div>
<div class="field"><label for="department_id">Department</label><select id="department_id" name="department_id"><option value="">Select department</option><?php foreach (($departments ?? []) as $d): ?><option value="<?= esc($d['department_id']) ?>" <?= (string)old('department_id',$user['author']['department_id']??'')===(string)$d['department_id']?'selected':'' ?>><?= esc($d['department_name']) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="subject_id">Subject</label><select id="subject_id" name="subject_id"><option value="">Select subject</option><?php foreach (($subjects ?? []) as $s): ?><option data-department="<?= esc($s['department_id']) ?>" value="<?= esc($s['subject_id']) ?>" <?= (string)old('subject_id',$user['author']['subject_id']??'')===(string)$s['subject_id']?'selected':'' ?>><?= esc($s['subject_name']) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="designation_id">Designation</label><select id="designation_id" name="designation_id"><option value="">Select designation (optional)</option><?php foreach (($designations ?? []) as $g): ?><option value="<?= esc($g['designation_id']) ?>" <?= (string)old('designation_id',$user['author']['designation_id']??'')===(string)$g['designation_id']?'selected':'' ?>><?= esc($g['designation_name']) ?></option><?php endforeach; ?></select></div>
</div></div><div class="actions"><button class="btn primary" type="submit">Save Account</button><a class="btn" href="<?= site_url('master/admin/users') ?>">Cancel</a></div></form></section></main>
<script>const role=document.getElementById('RollID'), box=document.getElementById('facultyFields'), dept=document.getElementById('department_id'), subject=document.getElementById('subject_id');function updateFaculty(){const show=['2','3'].includes(role.value);box.style.opacity=show?'1':'.65';dept.required=show;subject.required=show;Array.from(subject.options).forEach(o=>{if(!o.value)return;o.hidden=!!dept.value&&o.dataset.department!==dept.value;});if(subject.selectedOptions[0]?.hidden)subject.value='';}role.addEventListener('change',updateFaculty);dept.addEventListener('change',updateFaculty);updateFaculty();</script></body></html>